from itertools import combinations
import heapq


def _interval_solver(capacity, tie):
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        if mandatory & blocked or len(mandatory) > k:
            return {"error": "impossible"}
        options = [job for job in jobs if job["id"] not in blocked]
        best_value = None
        best_ids = None
        for subset in combinations(options, k):
            ids = [job["id"] for job in subset]
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            active = []
            valid = True
            for job in sorted(subset, key=lambda j: (j["start"], j["end"], j["id"])):
                while active and active[0] <= job["start"]:
                    heapq.heappop(active)
                heapq.heappush(active, job["end"])
                if len(active) > capacity:
                    valid = False
                    break
            if not valid:
                continue
            value = sum(job["value"] for job in subset)
            selected = sorted(ids)
            if (best_value is None or value > best_value or
                    (value == best_value and
                     (selected < best_ids if tie == "smallest" else selected > best_ids))):
                best_value, best_ids = value, selected
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


def _component_06(data):
    def rounded(n, d):
        if data["rounding"] == "floor":
            return n // d
        return (2 * n + d) // (2 * d)

    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)
    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(net * event.get("tax_bp", 0), 10000)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _component_07(data):
    packages = data["packages"]
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    names = sorted(packages)
    rows_by_version = {
        name: {row["version"]: row for row in packages[name]}
        for name in names
    }
    best = None
    best_versions = None

    def search(assigned, requirements, graph):
        nonlocal best, best_versions
        pending = sorted(set(requirements) - set(assigned))
        if not pending:
            state, finished = set(), set()

            def visit(name):
                if name in state:
                    return False
                if name in finished:
                    return True
                state.add(name)
                for dep in graph.get(name, []):
                    if not visit(dep):
                        return False
                state.remove(name)
                finished.add(name)
                return True

            if not all(visit(name) for name in graph):
                return
            vector = tuple(assigned.get(name, -1) for name in names)
            if best is None or vector < best:
                best = vector
                best_versions = dict(assigned)
            return

        name = pending[0]
        low, high = requirements[name]
        candidates = sorted(
            (v for v in rows_by_version[name]
             if low <= v <= high
             and v not in blocked.get(name, [])
             and (name not in pins or v == pins[name]))
        )
        for version in candidates:
            row = rows_by_version[name][version]
            new_assigned = dict(assigned)
            new_assigned[name] = version
            new_requirements = dict(requirements)
            new_graph = {n: list(ds) for n, ds in graph.items()}
            deps = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                deps.append(other)
                bounds = (dep["min"], dep["max"])
                if other in new_requirements:
                    old_low, old_high = new_requirements[other]
                    bounds = (max(old_low, bounds[0]), min(old_high, bounds[1]))
                new_requirements[other] = bounds
                if other in new_assigned and not bounds[0] <= new_assigned[other] <= bounds[1]:
                    break
            else:
                new_graph[name] = deps
                search(new_assigned, new_requirements, new_graph)

    roots = {name: tuple(bounds) for name, bounds in data["roots"].items()}
    search({}, roots, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _component_08(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit.get(data["source"], 0)
    start_state = (data["source"], initial_mask, data["coupons"])
    start_time = data["start"]
    distances = {start_state: start_time}
    queue = [(start_time, data["source"], initial_mask, data["coupons"])]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [(edge["duration"], remaining)]
            if remaining:
                durations.append((max(2, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            for duration, next_remaining in durations:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                dest = edge["v"]
                next_mask = mask | bit.get(dest, 0)
                next_state = (dest, next_mask, next_remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, dest, next_mask, next_remaining))
    return {"arrival": None}


SOLVERS = {
    "component_01": _interval_solver(1, "smallest"),
    "component_02": _interval_solver(2, "smallest"),
    "component_03": _interval_solver(1, "largest"),
    "component_04": _interval_solver(2, "largest"),
    "component_05": _interval_solver(1, "smallest"),
    "component_06": _component_06,
    "component_07": _component_07,
    "component_08": _component_08,
}
